import math, heapq, sys, time, traceback
sys.path.insert(0, '/app')
from lightlag_client import connect
from lightlag_surface import Surface, drive as sdrive, PHYSICS, TERRAIN_CODES

SAFE = 0.27
SLIP_MID = {"bedrock": 0.03, "regolith": 0.085, "sand": 0.25, "rocks": 0.18}
ECOST = {"bedrock": 0.3, "regolith": 0.36, "sand": 0.5, "rocks": 0.6}


def log(*a):
    print(*a, flush=True)


class Mission:
    def __init__(self, tools):
        self.t = tools
        self.rules = tools.rules()
        self.world = tools.map()
        self.mission = self.world["mission"]
        w = self.world
        self.S = Surface(w["cell_m"], w["elevation_cm"], w["terrain"])
        self.cell = w["cell_m"]
        self.nx, self.ny = self.S.nx - 1, self.S.ny - 1
        self.base = tuple(w["base"])
        self.T = self.rules["max_ticks"]
        self.delay = self.rules["delay_ticks"]
        self.eff = 0.8
        self.build_graph()
        self.trees = {}
        self.targets = {}
        self.sampled = set()
        self.pending_sample = {}  # tid -> exec tick
        self.update_targets()
        # estimation
        self.est = self.base
        self.est_tick = 0
        self.bias = 0.0
        self.gscale = 1.0
        self.cmds = {}  # exec_tick -> dict(cmd, sent)
        self.last_exec = 0
        self.packets_seen = 0
        self.battery = 100.0
        self.route = []
        self.need_replan = True
        self.cleared = set()

    # ---------- graph ----------
    def build_graph(self):
        S, nx, ny, c = self.S, self.nx, self.ny, self.cell
        bad = [[S.cell_max_slope(i, j) > 0.33 for i in range(nx)] for j in range(ny)]
        self.bad = bad
        adj = [[] for _ in range(nx * ny)]
        for j in range(ny):
            for i in range(nx):
                if bad[j][i]:
                    continue
                for di, dj in ((1, 0), (0, 1), (1, 1), (1, -1)):
                    i2, j2 = i + di, j + dj
                    if not (0 <= i2 < nx and 0 <= j2 < ny) or bad[j2][i2]:
                        continue
                    x1, y1 = (i + .5) * c, (j + .5) * c
                    x2, y2 = (i2 + .5) * c, (j2 + .5) * c
                    L = math.hypot(x2 - x1, y2 - y1)
                    ok = True
                    tsum = 0.0
                    n = 6
                    for k in range(n + 1):
                        f = k / n
                        x, y = x1 + (x2 - x1) * f, y1 + (y2 - y1) * f
                        h, gx, gy, code = S.sample(x, y)
                        if math.hypot(gx, gy) > SAFE:
                            ok = False
                            break
                        if k < n:
                            name = TERRAIN_CODES[code]
                            g = (gx * (x2 - x1) + gy * (y2 - y1)) / L
                            gain = PHYSICS["slip_grade_gain"][name]
                            s1 = min(.9, SLIP_MID[name] + gain * max(0, g))
                            s2 = min(.9, SLIP_MID[name] + gain * max(0, -g))
                            sp = 0.5 / (1 - s1) + 0.5 / (1 - s2)
                            pen = 1.0 + (0.25 if name in ("sand", "rocks") else 0)
                            tsum += sp * pen * (L / n) / 5.0
                    if not ok:
                        continue
                    a, b = j * nx + i, j2 * nx + i2
                    adj[a].append((b, tsum))
                    adj[b].append((a, tsum))
        self.adj = adj

    def cell_of(self, x, y):
        i = min(self.nx - 1, max(0, int(x / self.cell)))
        j = min(self.ny - 1, max(0, int(y / self.cell)))
        k = j * self.nx + i
        if self.adj[k]:
            return k
        # nearest connected cell
        best, bd = k, 1e9
        for dj in range(-3, 4):
            for di in range(-3, 4):
                i2, j2 = i + di, j + dj
                if 0 <= i2 < self.nx and 0 <= j2 < self.ny and self.adj[j2 * self.nx + i2]:
                    d = di * di + dj * dj
                    if d < bd:
                        bd, best = d, j2 * self.nx + i2
        return best

    def dijkstra(self, src):
        N = self.nx * self.ny
        dist = [1e18] * N
        pred = [-1] * N
        dist[src] = 0.0
        h = [(0.0, src)]
        adj = self.adj
        while h:
            d, u = heapq.heappop(h)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    pred[v] = u
                    heapq.heappush(h, (nd, v))
        return dist, pred

    def tree(self, key, x, y):
        if key not in self.trees:
            self.trees[key] = self.dijkstra(self.cell_of(x, y))
        return self.trees[key]

    def update_targets(self):
        for tg in self.world["targets"]:
            if tg["id"] not in self.targets:
                self.targets[tg["id"]] = tg
                self.need_replan = True

    # ---------- physics model ----------
    def sim(self, pos, cmd):
        if cmd["action"] != "drive":
            return pos
        r = sdrive(self.S, PHYSICS, pos[0], pos[1], cmd["heading_deg"] + self.bias, cmd["metres"], SLIP_MID)
        dx, dy = r["x"] - pos[0], r["y"] - pos[1]
        return (pos[0] + dx * self.gscale, pos[1] + dy * self.gscale)

    def solar(self, t):
        m = self.rules["sun_margin_ticks"]
        return self.rules["solar_peak"] * self.eff * math.sin(math.pi * (t + m) / (self.T + 2 * m))

    # ---------- telemetry ----------
    def ingest(self):
        pk = self.t.telemetry_log()
        pk = [p for p in pk if p.get("mission") == self.mission]
        new = pk[self.packets_seen:]
        self.packets_seen = len(pk)
        for p in new:
            tau = p["tick"]
            if p.get("charge", 0) > 0 and tau > 0:
                self.eff = max(0.8, min(1.0, p["charge"] / (self.rules["solar_peak"] * math.sin(math.pi * (tau + self.rules["sun_margin_ticks"]) / (self.T + 2 * self.rules["sun_margin_ticks"])))))
            self.battery = p["battery"]
            for s in p.get("sampled_targets", []):
                if s not in self.sampled:
                    self.sampled.add(s)
                    self.need_replan = True
            for tid, et in list(self.pending_sample.items()):
                if tau >= et:
                    del self.pending_sample[tid]
                    if tid not in self.sampled:
                        log("sample MISSED", tid)
                        self.need_replan = True
            if tau == 0:
                continue
            ev = p.get("events", [])
            stop = any(("tilt" in str(e) or "stop" in str(e) or "boundary" in str(e)) for e in ev)
            if ev:
                log("events", tau, ev)
            if any("discover" in str(e) for e in ev):
                self.world = self.t.map()
                self.update_targets()
            prior = self.est
            c = self.cmds.get(tau)
            if c and tau not in self.cleared:
                prior = self.sim(self.est, c["cmd"])
            meas = p["position"]
            if stop:
                self.est = (prior[0] + .7 * (meas[0] - prior[0]), prior[1] + .7 * (meas[1] - prior[1]))
                for et, cc in self.cmds.items():
                    if et > tau and cc["sent"] < tau:
                        self.cleared.add(et)
                self.need_replan = True
            else:
                K = 0.2
                rx, ry = meas[0] - prior[0], meas[1] - prior[1]
                self.est = (prior[0] + K * rx, prior[1] + K * ry)
                if c and c["cmd"]["action"] == "drive" and tau not in self.cleared:
                    d = math.hypot(prior[0] - self.est_prev_for(tau)[0], prior[1] - self.est_prev_for(tau)[1])
                    if d > 1.5:
                        h = math.radians(c["cmd"]["heading_deg"] + self.bias)
                        perp = -rx * math.sin(h) + ry * math.cos(h)
                        self.bias += math.degrees(0.04 * perp / d)
                        self.bias = max(-8, min(8, self.bias))
                        vo = p.get("visual_odometry", 0)
                        if vo > 0:
                            # predicted ground (unscaled)
                            self.gscale += 0.1 * (vo / (d / self.gscale) - self.gscale)
                            self.gscale = max(0.7, min(1.2, self.gscale))
            self._prev = (tau, self.est)
            self.est_tick = tau

    def est_prev_for(self, tau):
        return self._prevest

    # ---------- planning ----------
    def ticks_between(self, a_key, b):
        # a_key tree key, b (x,y)
        dist, _ = self.trees[a_key]
        return dist[self.cell_of(b[0], b[1])]

    def tval(self, tid, t):
        tg = self.targets[tid]
        if tg["deadline_tick"] is None or t <= tg["deadline_tick"]:
            return tg["value"]
        return tg["late_value"]

    def eval_route(self, start_t, D, route, start_bat):
        # route: list of tids; D(a,b) ticks; returns (value, end_t, minbat)
        t = start_t
        val = 0.0
        prev = "cur"
        bat = start_bat
        minbat = bat
        for tid in route + ["base"]:
            dt = D(prev, tid) * 1.08 + 1
            # energy
            for k in range(int(dt) + 1):
                bat = min(100, bat + self.solar(t + k)) - 0.15 - 2.0
                minbat = min(minbat, bat)
            t += dt + (1.5 if tid != "base" else 0)
            if tid != "base":
                val += self.tval(tid, t)
            prev = tid
        return val, t, minbat

    def plan(self, pos, start_t):
        cur = self.dijkstra(self.cell_of(*pos))
        cand = [tid for tid, tg in self.targets.items()
                if tid not in self.sampled and tid not in self.pending_sample]
        for tid in cand:
            tg = self.targets[tid]
            self.tree(tid, tg["x"], tg["y"])
        self.tree("base", *self.base)
        cache = {}

        def D(a, b):
            if (a, b) in cache:
                return cache[(a, b)]
            bp = self.base if b == "base" else (self.targets[b]["x"], self.targets[b]["y"])
            if a == "cur":
                v = cur[0][self.cell_of(*bp)]
            else:
                v = self.trees[a][0][self.cell_of(*bp)]
            if b != "base":
                v += math.hypot(bp[0] - ((self.cell_of(*bp) % self.nx) + .5) * self.cell,
                                bp[1] - ((self.cell_of(*bp) // self.nx) + .5) * self.cell) / 5
            cache[(a, b)] = v
            return v
        budget = self.T - 6
        bat0 = self.battery
        route = []
        val, endt, mb = self.eval_route(start_t, D, route, bat0)
        cand = [c for c in cand if D("cur", c) < 1e9 and D(c, "base") < 1e9]
        while True:
            best = None
            for c in cand:
                if c in route:
                    continue
                if self.targets[c].get("appear_tick", 0) > start_t:
                    continue
                for k in range(len(route) + 1):
                    r2 = route[:k] + [c] + route[k:]
                    v2, e2, m2 = self.eval_route(start_t, D, r2, bat0)
                    if e2 > budget or m2 < 8:
                        continue
                    dv = v2 - val
                    if dv <= 0:
                        continue
                    sc = dv / (e2 - endt + 2.0)
                    if best is None or sc > best[0]:
                        best = (sc, r2, v2, e2)
            if not best:
                break
            _, route, val, endt = best
        # 2-opt-ish improvement: try swapping adjacent
        improved = True
        while improved:
            improved = False
            for k in range(len(route) - 1):
                r2 = route[:]
                r2[k], r2[k + 1] = r2[k + 1], r2[k]
                v2, e2, m2 = self.eval_route(start_t, D, r2, bat0)
                if e2 <= budget and m2 >= 8 and (v2 > val + 1e-9 or (v2 >= val - 1e-9 and e2 < endt - 0.5)):
                    route, val, endt = r2, v2, e2
                    improved = True
        self.route = route
        self.plan_info = (val, endt)
        self.home_ticks = D("cur", "base")
        log("plan t=%d route=%s val=%.1f end=%.0f bat=%.0f bias=%.2f gs=%.3f" % (start_t, route, val, endt, bat0, self.bias, self.gscale))

    # ---------- steering ----------
    def line_safe(self, a, b):
        L = math.hypot(b[0] - a[0], b[1] - a[1])
        n = max(2, int(L / 1.0))
        for k in range(n + 1):
            f = k / n
            if self.S.slope(a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f) > SAFE + 0.02:
                return False
        return True

    def next_waypoint(self, pos, key, goal):
        dist, pred = self.trees[key]
        k = self.cell_of(*pos)
        chain = []
        cur = k
        for _ in range(8):
            if pred[cur] == -1:
                break
            cur = pred[cur]
            chain.append(((cur % self.nx + .5) * self.cell, (cur // self.nx + .5) * self.cell))
        pts = chain + [goal] if (len(chain) < 8) else chain
        best = pts[0] if pts else goal
        for p in pts:
            if math.hypot(p[0] - pos[0], p[1] - pos[1]) > 25:
                break
            if self.line_safe(pos, p):
                best = p
        if dist[k] > 1e17:
            best = goal
        return best

    def choose(self, pos, t_exec):
        # returns cmd
        if self.route:
            tid = self.route[0]
            tg = self.targets[tid]
            goal, key = (tg["x"], tg["y"]), tid
        else:
            tid = None
            goal, key = self.base, "base"
        d = math.hypot(goal[0] - pos[0], goal[1] - pos[1])
        if tid is not None and d < 0.8:
            self.pending_sample[tid] = t_exec
            self.route.pop(0)
            log("sample", tid, "at", t_exec, "est d=%.2f" % d)
            return {"action": "sample"}
        if tid is None and d < 1.2:
            return {"action": "wait"}
        if self.battery < 6 and t_exec < self.T - 60:
            return {"action": "wait"}
        wp = self.next_waypoint(pos, key, goal)
        if math.hypot(wp[0] - goal[0], wp[1] - goal[1]) < 1e-6 or d < 6:
            wp = goal
        dx, dy = wp[0] - pos[0], wp[1] - pos[1]
        dd = math.hypot(dx, dy)
        hdg = math.degrees(math.atan2(dy, dx))
        cmdh = (hdg - self.bias) % 360
        m = 5.0
        if wp == goal and dd < 6.5:
            # choose metres so we land on goal
            lo, hi = 0.05, 5.0
            for _ in range(14):
                mid = (lo + hi) / 2
                p2 = self.sim(pos, {"action": "drive", "heading_deg": cmdh, "metres": mid})
                if math.hypot(p2[0] - pos[0], p2[1] - pos[1]) < dd:
                    lo = mid
                else:
                    hi = mid
            m = round(max(0.05, min(5.0, (lo + hi) / 2)), 3)
        return {"action": "drive", "heading_deg": round(cmdh, 3), "metres": m}

    # ---------- loop ----------
    def predict_at(self, t_exec):
        pos = self.est
        for et in sorted(self.cmds):
            if self.est_tick < et < t_exec and et not in self.cleared:
                pos = self.sim(pos, self.cmds[et]["cmd"])
        return pos

    def run(self):
        now = 0
        self._prevest = self.est
        while True:
            self._prevest = self.est
            self.ingest_wrap()
            t_exec = max(now + self.delay + 1, self.last_exec + 1)
            if t_exec <= self.T and t_exec <= now + self.delay + 2:
                pos = self.predict_at(t_exec)
                if self.need_replan or now % 15 == 0:
                    self.need_replan = False
                    self.plan(pos, t_exec)
                # safety: go home if needed
                if self.route and hasattr(self, "home_ticks"):
                    pass
                cmd = self.choose(pos, t_exec)
                try:
                    ack = self.t.uplink([cmd])
                    et = ack[0]["execute_tick"] if isinstance(ack, list) else ack.get("execute_tick", ack.get("commands", [{}])[0].get("execute_tick", t_exec)) if isinstance(ack, dict) else t_exec
                except Exception as e:
                    log("uplink err", e, ack if 'ack' in dir() else '')
                    et = None
                if et is not None:
                    self.cmds[et] = {"cmd": cmd, "sent": now}
                    self.last_exec = et
            out = self.t.advance(1)
            now = out["current_tick"]
            if out.get("episode_complete") or out.get("mission") != self.mission:
                log("mission done", self.mission, out)
                return out

    def ingest_wrap(self):
        # ingest with per-packet previous estimate for d computation
        pk = None
        self._prevest = self.est
        orig_sim = self.sim
        self.ingest()


def main():
    with connect("http://lightlag:8000/mcp") as tools:
        while True:
            m = Mission(tools)
            log("=== mission", m.mission, "targets", len(m.targets))
            t0 = time.time()
            out = m.run()
            log("took", time.time() - t0)
            if out.get("campaign_complete"):
                break


if __name__ == "__main__":
    main()

